var n=`0795-bobotie`;var t=`world-0795`;var o=`ZA`;var a=`southern-africa`;var s=4;var r=74;var l={en:`Bobotie`,ua:`Боботі`};var d={en:`Bobotie is a South Africa classic prepared with yellow onion, ground beef, white bread, whole cow milk. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Боботі, страва кухні країни Південно-Африканська Республіка зі складниками: жовта цибуля, яловичий фарш, білий хліб, цільне коров'яче молоко. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,190,`g`],[`ground-beef`,690,`g`],[`sunflower-oil`,40,`ml`],[`curry-powder`,12,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`white-bread`,130,`g`],[`whole-cow-milk`,180,`ml`],[`apricot-jam`,55,`g`],[`raisin`,90,`g`],[`lemon-juice`,25,`ml`]]},{en:`Transfer the spiced mince to a baking dish, pour over the beaten egg-and-milk topping, tuck in bay leaves and bake until the custard is completely set.`,ua:`Перекладіть пряний фарш у форму, залийте збитими яйцями з молоком, додайте лаврове листя й запікайте до повної готовності яєчної заливки.`,t:[`layered-assembly`],m:10,i:[[`chicken-egg`,3,`pcs`],[`whole-cow-milk`,180,`ml`],[`bay-leaf`,3,`leaf`]]},{en:`Roast in a preheated 190°C oven for about 42 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 42 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:42,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`ground-turmeric`,4,`g`]]}];var g={slug:n,id:t,country:`ZA`,region:a,servings:4,minutes:74,title:l,text:d,steps:u};export{o as country,g as default,t as id,r as minutes,a as region,s as servings,n as slug,u as steps,d as text,l as title};